import { cn } from "@/lib/utils";
import SemanticIcon from "../icon/SemanticIcon.astro";
import type { HTMLAttributes } from "astro/types";

interface Props extends HTMLAttributes<"details"> {
  label: string;
  defaultOpen?: boolean;
  class?: string;
}

const { label, defaultOpen = false, class: className = "", ...rest } = Astro.props as Props;
---

<details
  {...rest}
  data-slot="hamburger-menu-group"
  open={defaultOpen}
  class={cn("group/hamburger-menu-group", className)}
>
  <summary class="flex min-h-10 cursor-pointer list-none items-center justify-between rounded-md py-2 pr-1 text-xs font-semibold leading-4 text-muted-foreground outline-none marker:hidden hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring [&::-webkit-details-marker]:hidden">
    {label}
    <SemanticIcon name="chevron-down" class="size-[18px] group-open/hamburger-menu-group:hidden" />
    <SemanticIcon name="chevron-up" class="hidden size-[18px] group-open/hamburger-menu-group:block" />
  </summary>
  <div data-slot="hamburger-menu-group-content" class="flex flex-col gap-1.5 pb-2">
    <slot />
  </div>
</details>

---
import { cn } from "@/lib/utils";
import type { HTMLAttributes } from "astro/types";

interface Props extends HTMLAttributes<"a"> {
  href: string;
  class?: string;
}

const { href, class: className = "", ...rest } = Astro.props as Props;
---

<a
  {...rest}
  href={href}
  data-slot="hamburger-menu-link"
  class={cn(
    "block rounded-md text-base font-medium leading-6 text-foreground outline-none hover:text-primary focus-visible:ring-2 focus-visible:ring-ring",
    className,
  )}
>
  <slot />
</a>

export { default as HamburgerMenu } from "./HamburgerMenu.astro";
export { default as MenuItem } from "./MenuItem.astro";
export { default as MenuGroup } from "./MenuGroup.astro";
